import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabaseClient';
import io from 'socket.io-client';

const StaffDashboard = ({ clinicId, staffId, staffName }) => {
    const [queue, setQueue] = useState([]);
    const [summary, setSummary] = useState({});
    const [socket, setSocket] = useState(null);
    const [loading, setLoading] = useState(true);
    
    useEffect(() => {
        // Connect to WebSocket
        const newSocket = io('http://localhost:3001', {
            auth: { userId: staffId, role: 'staff', clinicId }
        });
        setSocket(newSocket);
        
        newSocket.on('queue:updated', () => {
            fetchQueueFromDB();
            fetchSummary();
        });
        
        fetchQueueFromDB();
        fetchSummary();
        
        return () => newSocket.close();
    }, [clinicId]);
    
    const fetchQueueFromDB = async () => {
        try {
            const { data, error } = await supabase
                .from('Appointments')
                .select('id, patient_name, status, arrived_at, is_walk_in')
                .eq('ClinicID', clinicId)
                .in('status', ['waiting', 'in_consultation'])
                .order('arrived_at', { ascending: true });
            
            if (error) throw error;
            
            const formattedQueue = data.map((item, idx) => ({
                appointment_id: item.id,
                queue_position: idx + 1,
                patient_name: item.patient_name,
                waiting_minutes: Math.floor((new Date() - new Date(item.arrived_at)) / 60000),
                patient_status: item.status,
                is_walk_in: item.is_walk_in || false
            }));
            
            setQueue(formattedQueue);
            setLoading(false);
        } catch (error) {
            console.error('Error fetching queue:', error);
            setLoading(false);
        }
    };
    
    const fetchSummary = async () => {
        try {
            const { data, error } = await supabase
                .from('Appointments')
                .select('status')
                .eq('ClinicID', clinicId)
                .eq('appointment_date', new Date().toISOString().split('T')[0]);
            
            if (!error && data) {
                setSummary({
                    total_waiting: data.filter(a => a.status === 'waiting').length,
                    in_consultation_count: data.filter(a => a.status === 'in_consultation').length,
                    completed_today: data.filter(a => a.status === 'complete').length,
                    average_wait_minutes: 15
                });
            }
        } catch (error) {
            console.error('Error fetching summary:', error);
        }
    };
    
    const updateStatus = async (appointmentId, newStatus) => {
        // Update local state immediately
        setQueue(prev => prev.filter(p => p.appointment_id !== appointmentId));
        
        // Update in database
        const { error } = await supabase
            .from('Appointments')
            .update({ status: newStatus })
            .eq('id', appointmentId);
        
        if (error) {
            console.error('Error updating status:', error);
        }
        
        // Refresh data
        fetchQueueFromDB();
        fetchSummary();
    };
    
    const addTestPatient = async () => {
        const { error } = await supabase
            .from('Appointments')
            .insert({
                id: crypto.randomUUID(),
                patient_name: 'Test Patient ' + Math.floor(Math.random() * 100),
                ClinicID: clinicId,
                appointment_date: new Date().toISOString().split('T')[0],
                appointment_time: new Date().toLocaleTimeString(),
                status: 'waiting',
                is_walk_in: false,
                arrived_at: new Date().toISOString()
            });
        
        if (error) {
            console.error('Error adding test patient:', error);
            alert('Error: ' + error.message);
        } else {
            fetchQueueFromDB();
            fetchSummary();
            alert('Test patient added!');
        }
    };
    
    if (loading) {
        return <div style={{ padding: '40px', textAlign: 'center' }}>Loading dashboard...</div>;
    }
    
    return (
        <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <h1>🏥 Clinic Queue Management Dashboard</h1>
                <button 
                    onClick={addTestPatient}
                    style={{ background: '#6366f1', color: 'white', border: 'none', padding: '8px 16px', borderRadius: '6px', cursor: 'pointer' }}
                >
                    + Add Test Patient
                </button>
            </div>
            <p>Welcome, {staffName || 'Staff Member'}</p>
            <p>Clinic: Soweto Community Clinic | ID: {clinicId}</p>
            
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '15px', margin: '20px 0' }}>
                <div style={{ padding: '15px', background: '#fef3c7', borderRadius: '8px' }}>
                    <div>🕐 Waiting</div>
                    <div style={{ fontSize: '28px', fontWeight: 'bold' }}>{summary.total_waiting || 0}</div>
                </div>
                <div style={{ padding: '15px', background: '#d1fae5', borderRadius: '8px' }}>
                    <div>💚 In Consultation</div>
                    <div style={{ fontSize: '28px', fontWeight: 'bold' }}>{summary.in_consultation_count || 0}</div>
                </div>
                <div style={{ padding: '15px', background: '#dbeafe', borderRadius: '8px' }}>
                    <div>✅ Completed Today</div>
                    <div style={{ fontSize: '28px', fontWeight: 'bold' }}>{summary.completed_today || 0}</div>
                </div>
                <div style={{ padding: '15px', background: '#e9d5ff', borderRadius: '8px' }}>
                    <div>⏱️ Avg Wait Time</div>
                    <div style={{ fontSize: '28px', fontWeight: 'bold' }}>{summary.average_wait_minutes || 0} min</div>
                </div>
            </div>
            
            <div style={{ background: 'white', borderRadius: '8px', border: '1px solid #ddd', overflow: 'auto' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                    <thead style={{ background: '#f5f5f5' }}>
                        <tr>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Position</th>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Patient Name</th>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Wait Time</th>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Type</th>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Status</th>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {queue.map((patient) => (
                            <tr key={patient.appointment_id} style={{ borderBottom: '1px solid #eee' }}>
                                <td style={{ padding: '12px', fontWeight: 'bold' }}>{patient.queue_position}</td>
                                <td style={{ padding: '12px' }}>{patient.patient_name}</td>
                                <td style={{ padding: '12px' }}>{patient.waiting_minutes} min</td>
                                <td style={{ padding: '12px' }}>
                                    <span style={{
                                        padding: '2px 8px',
                                        borderRadius: '12px',
                                        background: patient.is_walk_in ? '#fed7aa' : '#bfdbfe'
                                    }}>
                                        {patient.is_walk_in ? 'Walk-in' : 'Scheduled'}
                                    </span>
                                </td>
                                <td style={{ padding: '12px' }}>
                                    <span style={{
                                        padding: '4px 8px',
                                        borderRadius: '20px',
                                        background: patient.patient_status === 'waiting' ? '#fef3c7' : '#d1fae5'
                                    }}>
                                        {patient.patient_status === 'waiting' ? 'Waiting' : 'In Consultation'}
                                    </span>
                                </td>
                                <td style={{ padding: '12px' }}>
                                    {patient.patient_status === 'waiting' && (
                                        <button 
                                            onClick={() => updateStatus(patient.appointment_id, 'in_consultation')}
                                            style={{ background: '#10b981', color: 'white', border: 'none', padding: '6px 12px', borderRadius: '6px', cursor: 'pointer' }}
                                        >
                                            Start Consultation
                                        </button>
                                    )}
                                    {patient.patient_status === 'in_consultation' && (
                                        <button 
                                            onClick={() => updateStatus(patient.appointment_id, 'complete')}
                                            style={{ background: '#3b82f6', color: 'white', border: 'none', padding: '6px 12px', borderRadius: '6px', cursor: 'pointer' }}
                                        >
                                            Complete
                                        </button>
                                    )}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
            
            {queue.length === 0 && (
                <div style={{ textAlign: 'center', padding: '40px', color: '#666' }}>
                    No patients in queue. Click "Add Test Patient" to add one!
                </div>
            )}
        </div>
    );
};

export default StaffDashboard;
